import type { Localized } from "./catalog";

export type ContentPage = {
  id: string;
  slug: Localized;
  title: Localized;
  eyebrow: Localized;
  intro: Localized;
  image?: string;
  sections: {
    heading: Localized;
    body: Localized;
    bullets?: Localized<string[]>;
  }[];
  faqs?: { q: Localized; a: Localized }[];
};

const t = (en: string, fr: string): Localized => ({ en, fr });
const b = (en: string[], fr: string[]): Localized<string[]> => ({ en, fr });
const s = (heading: Localized, body: Localized, bullets?: Localized<string[]>) => ({ heading, body, ...(bullets ? { bullets } : {}) });
const q = (question: Localized, answer: Localized) => ({ q: question, a: answer });

